<?php require __DIR__.'/bootstrap.php';$u=require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){foreach($_POST['plan']??[] as $id=>$data){$price=str_replace(',','.',preg_replace('~[^0-9,]~','',$data['price']??''));$name=trim($data['name']??'');$description=trim($data['description']??'');$active=isset($data['active'])?1:0;if($name&&is_numeric($price))$pdo->prepare('UPDATE plans SET name=?,monthly_price=?,description=?,active=? WHERE id=?')->execute([$name,$price,$description,$active,(int)$id]);}flash('ok','Planos e preços atualizados.');header('Location: admin_plans.php');exit;}$ok=flash('ok');$plans=$pdo->query('SELECT * FROM plans ORDER BY monthly_price')->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Planos e preços — Arena</title><link rel="stylesheet" href="assets/app.css"></head><body class="adminskin"><aside class="side"><a class="side-logo">ARENA DE <b>AÇO</b><small>ADMINISTRAÇÃO</small></a><a href="admin.php">⌂ Dashboard</a><a class="active" href="admin_plans.php">◈ Planos e preços</a><a href="admin_catalog.php">▣ Mangás e capítulos</a><a href="video_novo.php">▻ Vídeos Ultimate</a><a href="admin_tickets.php">♧ Suporte</a></aside><main class="adminmain"><header class="adminhead"><div><h1>Planos e preços</h1><span>Altere os valores exibidos na home e cobrados nas assinaturas.</span></div></header><?php if($ok):?><p class="alert ok"><?=e($ok)?></p><?php endif?><form method="post" class="price-editor"><?php foreach($plans as $p):?><article class="panel"><p class="super">CÓDIGO: <?=strtoupper(e($p['code']))?></p><label>Nome do plano<input name="plan[<?=$p['id']?>][name]" value="<?=e($p['name'])?>"></label><label>Preço mensal (R$)<input name="plan[<?=$p['id']?>][price]" value="<?=number_format((float)$p['monthly_price'],2,',','')?>"></label><label>Descrição<input name="plan[<?=$p['id']?>][description]" value="<?=e($p['description'])?>"></label><label class="check"><input type="checkbox" name="plan[<?=$p['id']?>][active]" <?=$p['active']?'checked':''?>> Plano visível para clientes</label></article><?php endforeach?><button class="redbtn">Salvar preços e planos →</button></form></main></body></html>
